/*
 * A243063  Numbers generated by a Fibonacci-like sequence in which zeros are
 *          suppressed.
 * https://oeis.org/A243063
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(1) = 1, a(2) = 1; for n>=3, a(n) = no-zero(a(n-2)+a(n-1))
 *            where no-zero removes all zero digits from the decimal
 *            representation of its argument
 * Range:     u8 n <= 13, u16 n <= 31, u32 n <= 927, u64 n <= 927,
 *            u128 n <= 927, big any n
 * Validated: standard, pass, 63 terms through n = 821 (2026-11-01)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>

/* Remove all zero digits from x. */
static seq_t no_zero_digits(seq_t x)
{
    /* The sequence never generates negative numbers, so x >= 0. */
    /* We collect non‑zero digits in reverse order, then rebuild. */
    int digits[64] = {0};   /* enough for 128‑bit numbers (~39 digits). */
    int len = 0;
    while (x > 0) {
        int d = (int)(x % 10);
        if (d != 0) {
            digits[len++] = d;
        }
        x /= 10;
    }
    seq_t res = 0;
    for (int i = len - 1; i >= 0; --i) {
        res = res * 10 + digits[i];
    }
    return res;
}

seq_t a(idx_t n)
{
    if (n == 1 || n == 2) {
        return (seq_t)1;
    }

    seq_t prev2 = (seq_t)1;   /* a(1) */
    seq_t prev1 = (seq_t)1;   /* a(2) */
    seq_t cur = 0;

    for (idx_t i = 3; i <= n; ++i) {
        cur = no_zero_digits(prev2 + prev1);
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}
